CREATE TABLE finops_aws_health_snapshots(generation_id text PRIMARY KEY CHECK(generation_id ~ '^hhg_[a-f0-9]{64}$'),org_id text NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,customer_id text NOT NULL REFERENCES customers(id) ON DELETE CASCADE,connection_id text NOT NULL REFERENCES aws_connections(id) ON DELETE CASCADE,account_id text NOT NULL CHECK(account_id ~ '^[0-9]{12}$'),partition text NOT NULL,endpoint_region text NOT NULL,capture_id text NOT NULL CHECK(capture_id ~ '^health_[a-f0-9]{64}$'),configuration_state text NOT NULL CHECK(configuration_state IN('ready','pending','unavailable','unverified')),collection_state text NOT NULL CHECK(collection_state IN('complete','partial','unavailable')),complete boolean NOT NULL,support_plan text NOT NULL,organization_view_status text NOT NULL,content_sha256 text NOT NULL CHECK(content_sha256 ~ '^[a-f0-9]{64}$'),snapshot_json text NOT NULL CHECK(octet_length(snapshot_json) BETWEEN 2 AND 67108864),observed_at text NOT NULL CHECK(char_length(observed_at)=24),event_count bigint NOT NULL CHECK(event_count BETWEEN 0 AND 10000),affected_account_count bigint NOT NULL CHECK(affected_account_count BETWEEN 0 AND 100000),affected_entity_count bigint NOT NULL CHECK(affected_entity_count BETWEEN 0 AND 200000),created_at bigint NOT NULL CHECK(created_at BETWEEN 0 AND 9007199254740991),UNIQUE(org_id,customer_id,connection_id,capture_id),CHECK(NOT complete OR(configuration_state='ready' AND collection_state='complete')));
CREATE INDEX finops_aws_health_history_idx ON finops_aws_health_snapshots(org_id,customer_id,connection_id,observed_at DESC,generation_id DESC);
CREATE TABLE finops_aws_health_heads(org_id text NOT NULL,customer_id text NOT NULL,connection_id text NOT NULL,active_generation_id text NOT NULL UNIQUE REFERENCES finops_aws_health_snapshots(generation_id),advanced_at bigint NOT NULL CHECK(advanced_at BETWEEN 0 AND 9007199254740991),PRIMARY KEY(org_id,customer_id,connection_id));
CREATE OR REPLACE FUNCTION finops_aws_health_snapshot_immutable()RETURNS trigger AS $$BEGIN RAISE EXCEPTION 'FINOPS_AWS_HEALTH_SNAPSHOT_IMMUTABLE';END;$$LANGUAGE plpgsql;
CREATE TRIGGER finops_aws_health_snapshots_update_guard BEFORE UPDATE ON finops_aws_health_snapshots FOR EACH ROW EXECUTE FUNCTION finops_aws_health_snapshot_immutable();CREATE TRIGGER finops_aws_health_snapshots_delete_guard BEFORE DELETE ON finops_aws_health_snapshots FOR EACH ROW EXECUTE FUNCTION finops_aws_health_snapshot_immutable();
CREATE OR REPLACE FUNCTION finops_aws_health_head_guard()RETURNS trigger AS $$DECLARE candidate finops_aws_health_snapshots%ROWTYPE;DECLARE active finops_aws_health_snapshots%ROWTYPE;BEGIN SELECT * INTO candidate FROM finops_aws_health_snapshots WHERE generation_id=NEW.active_generation_id;IF candidate.generation_id IS NULL OR NOT candidate.complete OR candidate.org_id<>NEW.org_id OR candidate.customer_id<>NEW.customer_id OR candidate.connection_id<>NEW.connection_id THEN RAISE EXCEPTION 'FINOPS_AWS_HEALTH_HEAD_REJECTED';END IF;IF TG_OP='UPDATE'THEN IF NEW.org_id<>OLD.org_id OR NEW.customer_id<>OLD.customer_id OR NEW.connection_id<>OLD.connection_id THEN RAISE EXCEPTION 'FINOPS_AWS_HEALTH_HEAD_REJECTED';END IF;SELECT * INTO active FROM finops_aws_health_snapshots WHERE generation_id=OLD.active_generation_id;IF NOT(candidate.observed_at>active.observed_at OR(candidate.observed_at=active.observed_at AND candidate.generation_id>active.generation_id))THEN RAISE EXCEPTION 'FINOPS_AWS_HEALTH_HEAD_REJECTED';END IF;END IF;RETURN NEW;END;$$LANGUAGE plpgsql;
CREATE TRIGGER finops_aws_health_heads_write_guard BEFORE INSERT OR UPDATE ON finops_aws_health_heads FOR EACH ROW EXECUTE FUNCTION finops_aws_health_head_guard();CREATE TRIGGER finops_aws_health_heads_delete_guard BEFORE DELETE ON finops_aws_health_heads FOR EACH ROW EXECUTE FUNCTION finops_aws_health_snapshot_immutable();
REVOKE ALL ON finops_aws_health_snapshots FROM PUBLIC;REVOKE ALL ON finops_aws_health_heads FROM PUBLIC;
